const {createHash} = require("crypto");
const target = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const base = "Quarterly Report 2026";
// all combinations: prefix space->char, space removal, 2026->_2026, lower
const out = [];
for (const lower of [true, false]) {
 for (const sp of [" ", "_", "-"]) {
  for (const year of ["2026", "_2026"]) {
   let s = base.replace("2026", year).replace(/ /g, sp);
   if (lower) s = s.toLowerCase();
   const d = createHash("sha256").update(s,"utf8").digest("hex");
   if (d === target) out.push(s);
  }
  // also collapsed spaces
  let s2 = base.replace("2026", year).replace(/ /g, "");
  if (lower) s2 = s2.toLowerCase();
  const d2 = createHash("sha256").update(s2,"utf8").digest("hex");
  if (d2 === target) out.push(s2);
 }
}
console.log("matches:", JSON.stringify(out));
'

