const {createHash} = require("crypto");
const target = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const words = ["Quarterly", "Report", "2026", "_2026"];
const joins = ["-", "_", "", " ", "+", "~", ".", "/"];
const out = [];
for (const a of words) for (const j1 of joins) for (const b of ["Report"]) for (const j2 of joins) for (const c of words.slice(2)) {
  for (const lower of [true,false]) {
    let s = [a, b, c].join("") ; // build manually with joins
    s = a + j1 + b + j2 + c;
    if (lower) s = s.toLowerCase();
    if (createHash("sha256").update(s,"utf8").digest("hex") === target) out.push(s);
  }
}
console.log("matches:", JSON.stringify([...new Set(out)]));
'
